const assert=require('node:assert/strict'),H=require('./model');
let count=0;function test(name,fn){fn();count++;console.log('PASS '+name)}
test('独立赛事的相同选手名不串分',()=>{const [a,b]=H.seed();const before=H.leaderboard(b,'all','player');a.matches[0].penalties.push({playerId:a.players[0].id,amount:200,scope:'both',reason:'测试'});assert.deepEqual(H.leaderboard(b,'all','player'),before)});
test('罚分范围分别作用，且不改变点棒顺位',()=>{const t=H.makeTournament('x','x','team'),m=H.newMatch(t);m.penalties=[{playerId:t.players[0].id,amount:200,scope:'both',reason:'测试'},{playerId:t.players[1].id,amount:100,scope:'personal',reason:'测试'},{playerId:t.players[2].id,amount:50,scope:'team',reason:'测试'}];const r=H.scoreMatch(m,t);assert.deepEqual(r.map(s=>[s.rank,s.net,s.teamNet]),[[1,416,416],[2,0,100],[3,-200,-250],[4,-516,-516]])});
test('役满标记不改变分数，允许同场多个事件',()=>{const t=H.makeTournament('x','x','team'),m=H.newMatch(t),before=H.scoreMatch(m,t);m.yakuman=[{playerId:t.players[0].id,types:['大三元'],multiplier:1,round:'南1局'},{playerId:t.players[1].id,types:['四暗刻','字一色'],multiplier:2,round:'南2局'}];assert.deepEqual(H.scoreMatch(m,t),before)});
test('罚分无原因不得发布',()=>{const t=H.makeTournament('x','x','team'),m=H.newMatch(t);m.penalties=[{playerId:t.players[0].id,amount:200,scope:'both',reason:' '}];assert.throws(()=>H.publish(t,m),/原因/)});
test('个人赛拒绝队伍罚分',()=>{const t=H.makeTournament('x','x','individual'),m=H.newMatch(t);m.penalties=[{playerId:t.players[0].id,amount:200,scope:'team',reason:'测试'}];assert.throws(()=>H.scoreMatch(m,t),/范围/);assert.deepEqual(H.leaderboard(t,'all','team'),[])});
test('拒绝跨赛事对局和重复参赛者',()=>{const a=H.makeTournament('a','a','team'),b=H.makeTournament('b','b','team'),m=H.newMatch(a);assert.throws(()=>H.scoreMatch(m,b),/赛事不匹配/);m.seats[1].playerId=m.seats[0].playerId;assert.throws(()=>H.scoreMatch(m,a),/不同/)});
test('协会供托留存校验与 ML 分配策略分离',()=>{const t=H.makeTournament('x','x','individual','npm'),m=H.newMatch(t);m.seats[0].score-=1000;m.deposit=1000;assert.equal(H.scoreMatch(m,t).reduce((a,s)=>a+s.net,0),-10);m.rules.kyotaku='distributed';assert.throws(()=>H.scoreMatch(m,t),/先分配/)});
test('未配置参考规则不冒充官方可用模板',()=>{const t=H.makeTournament('x','x','individual','renmei');assert.throws(()=>H.publish(t,H.newMatch(t)),/参考模板/)});
test('正负分不同舍入方向与精确一半',()=>{assert.equal(H.transform(1013,1,2,'ceil'),507);assert.equal(H.transform(-1013,1,2,'ceil'),-506);assert.equal(H.transform(-1013,1,2,'halfAway'),-507);assert.equal(H.transform(-1013,1,2,'trunc'),-506);assert.equal(H.transform(1013,0,1,'ceil'),0);assert.throws(()=>H.transform(100,1,0,'ceil'))});
const opt={numerator:1,denominator:2,rounding:'ceil',penalties:'scale'};
test('结算预览不改变榜单',()=>{const [t]=H.seed(),before=JSON.stringify(t);H.settlementPreview(t,'r','s','team',opt);assert.equal(JSON.stringify(t),before)});
test('人工覆盖需要原因，确认一次且不重复入账',()=>{const [t]=H.seed(),p=H.settlementPreview(t,'r','s','team',opt);p.rows[0].final+=10;assert.throws(()=>H.commitSettlement(t,p),/原因/);p.rows[0].reason='裁定补正';H.commitSettlement(t,p);assert.equal(t.carries.length,4);assert.throws(()=>H.commitSettlement(t,p),/变化/);assert.equal(t.carries.length,4)});
test('全赛事原始累计不受带入影响，个人不随队伍折半',()=>{const [t]=H.seed(),before=H.leaderboard(t,'all','team'),personal=H.leaderboard(t,'all','player'),p=H.settlementPreview(t,'r','s','team',opt);H.commitSettlement(t,p);assert.deepEqual(H.leaderboard(t,'all','team'),before);assert.deepEqual(H.leaderboard(t,'all','player'),personal);const next=H.leaderboard(t,'s','team','competitive');assert.equal(next.reduce((n,r)=>n+r.total,0),p.rows.reduce((n,r)=>n+r.final,0));assert.equal(H.leaderboard(t,'s','player','competitive').reduce((n,r)=>n+r.total,0),0)});
test('来源修改导致旧预览失效',()=>{const [t]=H.seed(),p=H.settlementPreview(t,'r','s','team',opt);t.revision++;assert.throws(()=>H.commitSettlement(t,p),/重新生成/)});
test('未发布比赛和目标已有比赛阻止结算',()=>{let [t]=H.seed();H.newMatch(t);assert.throws(()=>H.settlementPreview(t,'r','s','team',opt),/未发布/);[t]=H.seed();H.newMatch(t,'s');assert.throws(()=>H.settlementPreview(t,'r','s','team',opt),/目标阶段/)});
test('阶段锁定禁止新增半庄',()=>{const [t]=H.seed();H.commitSettlement(t,H.settlementPreview(t,'r','s','team',opt));assert.throws(()=>H.newMatch(t,'r'),/锁定/)});
test('规则编辑不会改变旧对局快照',()=>{const t=H.makeTournament('x','x','team'),m=H.newMatch(t);t.rules.bonuses[0]=40;assert.equal(H.scoreMatch(m,t)[0].base,616)});
test('完整保留罚分的结算策略',()=>{const [t]=H.seed(),p=H.settlementPreview(t,'r','s','team',{...opt,penalties:'full'});p.rows.forEach(r=>assert.equal(r.suggested,H.transform(r.total-r.penalty,1,2,'ceil')+r.penalty))});
console.log(count+' domain cases passed');
